diff --git a/lib/ftplistparser.c b/lib/ftplistparser.c
index f416308e1..aaf91f311 100644
--- a/lib/ftplistparser.c
+++ b/lib/ftplistparser.c
@@ -408,161 +408,161 @@ static CURLcode parse_unix(struct Curl_easy *data,

   switch(parser->state.UNIX.main) {
   case PL_UNIX_TOTALSIZE:
     switch(parser->state.UNIX.sub.total_dirsize) {
     case PL_UNIX_TOTALSIZE_INIT:
       if(c == 't') {
         parser->state.UNIX.sub.total_dirsize = PL_UNIX_TOTALSIZE_READING;
         parser->item_length++;
       }
       else {
         parser->state.UNIX.main = PL_UNIX_FILETYPE;
         /* continue to fall through */
       }
       break;
     case PL_UNIX_TOTALSIZE_READING:
       parser->item_length++;
       if(c == '\r') {
         parser->item_length--;
         curlx_dyn_setlen(&infop->buf, --len);
       }
       else if(c == '\n') {
         mem[parser->item_length - 1] = 0;
         if(!strncmp("total ", mem, 6)) {
           const char *endptr = mem + 6;
           /* here we can deal with directory size, pass the leading
              whitespace and then the digits */
           curlx_str_passblanks(&endptr);
           while(ISDIGIT(*endptr))
             endptr++;
           if(*endptr) {
             return CURLE_FTP_BAD_FILE_LIST;
           }
           parser->state.UNIX.main = PL_UNIX_FILETYPE;
           curlx_dyn_reset(&infop->buf);
         }
         else
           return CURLE_FTP_BAD_FILE_LIST;

       }
       break;
     }
     if(parser->state.UNIX.main != PL_UNIX_FILETYPE)
       break;
     FALLTHROUGH();
   case PL_UNIX_FILETYPE:
     result = unix_filetype(c, &finfo->filetype);
     if(result)
       return result;
     parser->state.UNIX.main = PL_UNIX_PERMISSION;
     parser->item_length = 0;
     parser->item_offset = 1;
     break;
   case PL_UNIX_PERMISSION:
     parser->item_length++;
     if((parser->item_length <= 9) && !strchr("rwx-tTsS", c))
       return CURLE_FTP_BAD_FILE_LIST;

     else if(parser->item_length == 10) {
       unsigned int perm;
       if(c != ' ')
         return CURLE_FTP_BAD_FILE_LIST;

       mem[10] = 0; /* terminate permissions */
       perm = ftp_pl_get_permission(mem + parser->item_offset);
       if(perm & FTP_LP_MALFORMATED_PERM)
         return CURLE_FTP_BAD_FILE_LIST;

       parser->file_data->info.flags |= CURLFINFOFLAG_KNOWN_PERM;
       parser->file_data->info.perm = perm;
       parser->offsets.perm = parser->item_offset;

       parser->item_length = 0;
       parser->state.UNIX.main = PL_UNIX_HLINKS;
       parser->state.UNIX.sub.hlinks = PL_UNIX_HLINKS_PRESPACE;
     }
     break;
   case PL_UNIX_HLINKS:
     switch(parser->state.UNIX.sub.hlinks) {
     case PL_UNIX_HLINKS_PRESPACE:
       if(c != ' ') {
-        if(ISDIGIT(c)) {
+        if(ISDIGIT(c) && len) {
           parser->item_offset = len - 1;
           parser->item_length = 1;
           parser->state.UNIX.sub.hlinks = PL_UNIX_HLINKS_NUMBER;
         }
         else
           return CURLE_FTP_BAD_FILE_LIST;
       }
       break;
     case PL_UNIX_HLINKS_NUMBER:
       parser->item_length ++;
       if(c == ' ') {
         const char *p = &mem[parser->item_offset];
         curl_off_t hlinks;
         mem[parser->item_offset + parser->item_length - 1] = 0;

         if(!curlx_str_number(&p, &hlinks, LONG_MAX)) {
           parser->file_data->info.flags |= CURLFINFOFLAG_KNOWN_HLINKCOUNT;
           parser->file_data->info.hardlinks = (long)hlinks;
         }
         parser->item_length = 0;
         parser->item_offset = 0;
         parser->state.UNIX.main = PL_UNIX_USER;
         parser->state.UNIX.sub.user = PL_UNIX_USER_PRESPACE;
       }
       else if(!ISDIGIT(c))
         return CURLE_FTP_BAD_FILE_LIST;

       break;
     }
     break;
   case PL_UNIX_USER:
     switch(parser->state.UNIX.sub.user) {
     case PL_UNIX_USER_PRESPACE:
       if(c != ' ') {
         parser->item_offset = len - 1;
         parser->item_length = 1;
         parser->state.UNIX.sub.user = PL_UNIX_USER_PARSING;
       }
       break;
     case PL_UNIX_USER_PARSING:
       parser->item_length++;
       if(c == ' ') {
         mem[parser->item_offset + parser->item_length - 1] = 0;
         parser->offsets.user = parser->item_offset;
         parser->state.UNIX.main = PL_UNIX_GROUP;
         parser->state.UNIX.sub.group = PL_UNIX_GROUP_PRESPACE;
         parser->item_offset = 0;
         parser->item_length = 0;
       }
       break;
     }
     break;
   case PL_UNIX_GROUP:
     switch(parser->state.UNIX.sub.group) {
     case PL_UNIX_GROUP_PRESPACE:
       if(c != ' ') {
         parser->item_offset = len - 1;
         parser->item_length = 1;
         parser->state.UNIX.sub.group = PL_UNIX_GROUP_NAME;
       }
       break;
     case PL_UNIX_GROUP_NAME:
       parser->item_length++;
       if(c == ' ') {
         mem[parser->item_offset + parser->item_length - 1] = 0;
         parser->offsets.group = parser->item_offset;
         parser->state.UNIX.main = PL_UNIX_SIZE;
         parser->state.UNIX.sub.size = PL_UNIX_SIZE_PRESPACE;
         parser->item_offset = 0;
         parser->item_length = 0;
       }
       break;
     }
     break;
   case PL_UNIX_SIZE:
     switch(parser->state.UNIX.sub.size) {
     case PL_UNIX_SIZE_PRESPACE:
       if(c != ' ') {
         if(ISDIGIT(c)) {
           parser->item_offset = len - 1;
@@ -773,161 +773,161 @@ static CURLcode parse_unix(struct Curl_easy *data,
         parser->offsets.symlink_target = parser->item_offset;
         result = ftp_pl_insert_finfo(data, infop);
         if(result)
           return result;

         parser->state.UNIX.main = PL_UNIX_FILETYPE;
       }
       break;
     case PL_UNIX_SYMLINK_WINDOWSEOL:
       if(c == '\n') {
         mem[parser->item_offset + parser->item_length - 1] = 0;
         parser->offsets.symlink_target = parser->item_offset;
         result = ftp_pl_insert_finfo(data, infop);
         if(result)
           return result;

         parser->state.UNIX.main = PL_UNIX_FILETYPE;
       }
       else
         return CURLE_FTP_BAD_FILE_LIST;

       break;
     }
     break;
   }
   return CURLE_OK;
 }

 static CURLcode parse_winnt(struct Curl_easy *data,
                             struct ftp_parselist_data *parser,
                             struct fileinfo *infop,
                             const char c)
 {
   struct curl_fileinfo *finfo = &infop->info;
   size_t len = curlx_dyn_len(&infop->buf);
   char *mem = curlx_dyn_ptr(&infop->buf);
   CURLcode result = CURLE_OK;

   switch(parser->state.NT.main) {
   case PL_WINNT_DATE:
     parser->item_length++;
     if(parser->item_length < 9) {
       if(!strchr("0123456789-", c)) { /* only simple control */
         return CURLE_FTP_BAD_FILE_LIST;
       }
     }
     else if(parser->item_length == 9) {
       if(c == ' ') {
         parser->state.NT.main = PL_WINNT_TIME;
         parser->state.NT.sub.time = PL_WINNT_TIME_PRESPACE;
       }
       else
         return CURLE_FTP_BAD_FILE_LIST;
     }
     else
       return CURLE_FTP_BAD_FILE_LIST;
     break;
   case PL_WINNT_TIME:
     parser->item_length++;
     switch(parser->state.NT.sub.time) {
     case PL_WINNT_TIME_PRESPACE:
       if(!ISBLANK(c))
         parser->state.NT.sub.time = PL_WINNT_TIME_TIME;
       break;
     case PL_WINNT_TIME_TIME:
       if(c == ' ') {
         parser->offsets.time = parser->item_offset;
         mem[parser->item_offset + parser->item_length -1] = 0;
         parser->state.NT.main = PL_WINNT_DIRORSIZE;
         parser->state.NT.sub.dirorsize = PL_WINNT_DIRORSIZE_PRESPACE;
         parser->item_length = 0;
       }
       else if(!strchr("APM0123456789:", c))
         return CURLE_FTP_BAD_FILE_LIST;
       break;
     }
     break;
   case PL_WINNT_DIRORSIZE:
     switch(parser->state.NT.sub.dirorsize) {
     case PL_WINNT_DIRORSIZE_PRESPACE:
-      if(c != ' ') {
+      if(c != ' ' && len) {
         parser->item_offset = len - 1;
         parser->item_length = 1;
         parser->state.NT.sub.dirorsize = PL_WINNT_DIRORSIZE_CONTENT;
       }
       break;
     case PL_WINNT_DIRORSIZE_CONTENT:
       parser->item_length ++;
       if(c == ' ') {
         mem[parser->item_offset + parser->item_length - 1] = 0;
